export function obtenerGuiaPorSlug(slug: string): GuiaItem | undefined {
  return TODAS_LAS_GUIAS.find((g) => g.slug === slug);
}

export function obtenerAnteriorGuia(slug: string): GuiaItem | undefined {
  const idx = TODAS_LAS_GUIAS.findIndex((g) => g.slug === slug);
  if (idx <= 0) return undefined;
  return TODAS_LAS_GUIAS[idx - 1];
}

export function obtenerSiguienteGuia(slug: string): GuiaItem | undefined {
  const idx = TODAS_LAS_GUIAS.findIndex((g) => g.slug === slug);
  if (idx === -1 || idx >= TODAS_LAS_GUIAS.length - 1) return undefined;
  return TODAS_LAS_GUIAS[idx + 1];
}

export function obtenerGuiasPorCategoria(categoria: CategoriaGuia): GuiaItem[] {
  return TODAS_LAS_GUIAS.filter((g) => g.categoria === categoria);
}
